  "trend_analysis_data": {
    "global_trends": [
      {
        "trend_name": "常设与临时展览的灵活结合",
        "description": "现代科技馆倾向于在空间规划上同时包含核心常设展厅与可变的临时展厅，以平衡经典科普内容的展示与前沿科技/短期主题的更新需求。",
        "evidence_cases": [
          {
            "case_name": "Museum of Medical History and Innovation",
            "snippet": "core and changing exhibition galleries"
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "35,000 sqm of permanent and temporary exhibition halls and galleries."
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "以中庭为核心的流动性空间布局",
        "description": "利用中庭作为核心枢纽，通过辐射状或悬浮式的展厅布局，利用视觉线索直观地引导观众流线，增强不同展区间的连通性与导向性。",
        "evidence_cases": [
          {
            "case_name": "New Science and Technology Museum of Henan Province",
            "snippet": "radiating from the atrium's three wings."
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "The many galleries emerge from the floor and walls of its central atrium... each giving visual clues that intuitively direct visitors through the museum's series of interconnected spaces."
          },
          {
            "case_name": "Yibin Science and Technology Museum",
            "snippet": "ensure the overall continuity of the exhibition hall."
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "融合休憩与观景的沉浸式参观体验",
        "description": "展览设计不再仅关注展品陈列，而是将休憩空间、观景露台与展览流线深度融合，为观众提供沉思与放松的场所，提升整体参观舒适度。",
        "evidence_cases": [
          {
            "case_name": "Yibin Science and Technology Museum",
            "snippet": "enter the second-floor exhibition hall, where you can have a good view and rest."
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "Terraces provide places for rest and contemplation while exploring the exhibitions."
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "多学科融合的综合性展览体系",
        "description": "大型科技馆项目趋向于打破单一学科界限，整合自然、天文、智能等多个领域，构建宏大且主题多元的综合展览体系。",
        "evidence_cases": [
          {
            "case_name": "New Science and Technology Museum of Henan Province",
            "snippet": "integrates the Science Museum, the Nature Museum, and the Astronomy Museum. Nearly 20 large exhibition halls themed around \"Nature, Astronomy, and Intelligence\""
          }
        ],
        "is_general_knowledge": false
      }
    ],
    "innovative_features": [
      "悬浮式展厅设计 (Galleries floating above the atrium)",
      "直观的视觉导向系统 (Visual clues directing visitors)",
      "融合自然、天文与智能的多馆合一模式 (Integration of Science, Nature, and Astronomy Museums)",
      "展览流线中的观景与休憩露台 (Terraces for rest and contemplation within exhibitions)",
      "入口处标志性骨架展示 (Prominently featured skeleton at entrance)"
    ]
  },
